/**
 * The favicon files that non-production environments swap in, so a development or staging tab is never mistaken for
 * production. Generated by `pnpm icons:brand`; the web app's Vite dev server applies the same swap for `pnpm start`.
 */
const ENVIRONMENT_FAVICON_PREFIX: Record<string, string> = {
  development: 'favicon-development-',
  staging: 'favicon-staging-',
};

const SIZED_FAVICON_RE = /\/assets\/images\/favicon-(\d+x\d+\.png)/g;

export function applyEnvironmentFavicons(html: string, environment: string): string {
  const prefix = ENVIRONMENT_FAVICON_PREFIX[environment];
  if (!prefix) {
    return html;
  }
  return html.replace(SIZED_FAVICON_RE, `/assets/images/${prefix}$1`);
}
